def _set_attributes(self, params: Optional[List[Any]] = None) -> None:
    """
    Set attributes from the input list of parameters.

    Args:
        params (list): list of parameters.
    """

    if params:
        for k, v in params.items():
            if k != "self" and not k.startswith("_"):
                setattr(self, k, v)
